1	{% extends "base.html" %}
2	{% from "_macros.html" import meta_badge, user_badge, cover %}
3	{% block title %}Игры Metacritic{% endblock %}
4	{% block content %}
5	<div class="page-head">
6	  <div>
7	    <h1>Новые игры с Metacritic</h1>
8	    <p class="muted">В базе {{ games_in_db }} {{ games_in_db|plural('игра', 'игры', 'игр') }}. Сервис раз в {{ interval_label }} забирает до {{ batch_size }} новых игр и обновляет уже известные.</p>
9	  </div>
10	  <a class="btn ghost" href="/monitor">Мониторинг{% if running %} · идёт обработка{% endif %}</a>
11	</div>
12	
13	<form class="card filters" method="get" action="/" id="filters">
14	  <input class="q" type="search" name="q" value="{{ q }}" placeholder="Поиск по названию" aria-label="Поиск по названию">
15	  <select name="platform" aria-label="Платформа" data-autosubmit>
16	    <option value="">Все платформы</option>
17	    {% for p in platforms %}
18	    <option value="{{ p.name }}" {% if p.name == platform %}selected{% endif %}>{{ p.name }} ({{ p.games }})</option>
19	    {% endfor %}
20	  </select>
21	  <select name="sort" aria-label="Сортировка" data-autosubmit>
22	    {% for key, label in sort_labels.items() %}
23	    <option value="{{ key }}" {% if key == sort %}selected{% endif %}>{{ label }}</option>
24	    {% endfor %}
25	  </select>
26	  <button class="btn" type="submit">Найти</button>
27	</form>
28	
29	<div class="filter-meta">
30	  <span class="muted small">Найдено: {{ total }}{% if platform %} · оценки показаны для платформы {{ platform }}{% endif %}</span>
31	  {% if q or platform or sort != 'date_desc' %}<a class="small" href="/">Сбросить фильтры</a>{% endif %}
32	</div>
33	
34	{% if games %}
35	<div class="grid">
36	  {% for g in games %}
37	  <a class="card game-tile" href="/game/{{ g.slug|urlencode }}">
38	    {{ cover(g.cover_url, g.title) }}
39	    <div class="tile-body">
40	      <div class="tile-title">{{ g.title }}</div>
41	      <div class="tile-meta">{{ g.release_date|date_ru }}{% if g.developers %} · {{ g.developers[0] }}{% endif %}</div>
42	      <div class="chips">
43	        {% for p in g.platforms[:5] %}<span class="chip {% if p.name == platform %}accent{% endif %}" title="{{ p.name }}">{{ p.short }}</span>{% endfor %}
44	        {% if g.platforms|length > 5 %}<span class="chip">+{{ g.platforms|length - 5 }}</span>{% endif %}
45	      </div>
46	      <div class="scores">
47	        {{ meta_badge(g.score_meta) }}<span class="score-label">Meta<br>score</span>
48	        {{ user_badge(g.score_user) }}<span class="score-label">User<br>score</span>
49	      </div>
50	    </div>
51	  </a>
52	  {% endfor %}
53	</div>
54	{% if pages > 1 %}
55	<nav class="pager">
56	  {% if page > 1 %}<a href="{{ page_url(page - 1) }}">← Назад</a>{% endif %}
57	  {% for n in range(1, pages + 1) %}
58	    {% if n == page %}<span class="current">{{ n }}</span>
59	    {% elif n == 1 or n == pages or (n - page)|abs <= 2 %}<a href="{{ page_url(n) }}">{{ n }}</a>
60	    {% elif (n - page)|abs == 3 %}<span>…</span>{% endif %}
61	  {% endfor %}
62	  {% if page < pages %}<a href="{{ page_url(page + 1) }}">Вперёд →</a>{% endif %}
63	</nav>
64	{% endif %}
65	{% else %}
66	<div class="card empty">
67	  {% if games_in_db == 0 %}
68	  <h2>Игр пока нет</h2>
69	  <p class="muted">Первая обработка запускается автоматически вскоре после старта сервиса. Её ход видно на странице мониторинга, там же можно запустить обработку вручную.</p>
70	  <a class="btn" href="/monitor">Открыть мониторинг</a>
71	  {% else %}
72	  <h2>Ничего не найдено</h2>
73	  <p class="muted">Попробуйте изменить запрос или выбрать другую платформу.</p>
74	  <a class="btn ghost" href="/">Сбросить фильтры</a>
75	  {% endif %}
76	</div>
77	{% endif %}
78	{% endblock %}
79

1	(function () {
2	  document.querySelectorAll("[data-autosubmit]").forEach(function (el) {
3	    el.addEventListener("change", function () { el.form.submit(); });
4	  });
5	
6	  var TZ = (document.body && document.body.dataset.tz) || undefined;
7	  var STATUS = {
8	    idle: "ожидает", running: "работает", waiting: "ждёт запуска", ok: "в норме", error: "ошибка",
9	    off: "выключен", partial: "частично", failed: "сбой", empty: "нечего обрабатывать", interrupted: "прерван",
10	    cut: "остановлен по времени", skipped: "пропускается"
11	  };
12	  var TRIGGER = { manual: "вручную", schedule: "по расписанию", startup: "при старте" };
13	
14	  function esc(s) {
15	    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
16	      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
17	    });
18	  }
19	
20	  function fmt(iso) {
21	    if (!iso) return "—";
22	    var d = new Date(iso);
23	    if (isNaN(d)) return String(iso);
24	    try {
25	      return new Intl.DateTimeFormat("ru-RU", {
26	        timeZone: TZ, day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit"
27	      }).format(d).replace(",", "");
28	    } catch (e) {
29	      return d.toLocaleString("ru-RU");
30	    }
31	  }
32	
33	  function wait(seconds) {
34	    seconds = Math.max(0, Math.ceil(seconds));
35	    var m = Math.floor(seconds / 60), s = seconds % 60;
36	    return m + ":" + (s < 10 ? "0" : "") + s;
37	  }
38	
39	  function setText(id, value) {
40	    var el = document.getElementById(id);
41	    if (el) el.textContent = value;
42	  }
43	
44	  function setProgress(pct) {
45	    var bar = document.getElementById("progress-bar");
46	    if (bar) bar.style.width = Math.max(0, Math.min(100, pct || 0)) + "%";
47	  }
48	
49	  var manual = null;
50	  var pending = false;
51	
52	  function renderButton() {
53	    var btn = document.getElementById("run-btn");
54	    var hint = document.getElementById("run-hint");
55	    if (!btn || pending || !manual) return;
56	    var text = "Запустить обработку сейчас";
57	    var disabled = false;
58	    var hintText = "Ручных запусков сегодня: " + manual.runs_today + (manual.daily_cap ? " из " + manual.daily_cap : "") +
59	      ". После каждого запуска пауза " + Math.round(manual.cooldown_seconds / 60) + " мин.";
60	    if (manual.code === "busy") {
61	      text = "Обработка идёт…";
62	      disabled = true;
63	    } else if (manual.code === "cooldown" || manual.code === "cap") {
64	      var left = manual.available_at ? (new Date(manual.available_at) - Date.now()) / 1000 : manual.retry_after;
65	      if (left > 0) {
66	        disabled = true;
67	        text = manual.code === "cap" ? "Лимит ручных запусков на сегодня" : "Запуск через " + wait(left);
68	        hintText = manual.reason || hintText;
69	      }
70	    }
71	    btn.disabled = disabled;
72	    btn.textContent = text;
73	    if (hint) hint.textContent = hintText;
74	  }
75	
76	  function render(st) {
77	    var p = st.progress || {};
78	    var running = !!st.running;
79	    document.getElementById("run-dot").className = "dot " + (running ? "running" : "idle");
80	    setText("run-state", running ? "Идёт обработка" : "Ожидание");
81	    setText("run-step", p.step ? p.step + (p.current && p.step.indexOf(p.current) < 0 ? ": " + p.current : "") : "");
82	    setProgress(p.total ? Math.round(100 * p.done / p.total) : 0);
83	    setText("progress-text", p.total
84	      ? "Запуск #" + p.run_id + ": " + p.done + " из " + p.total + " · успешно " + p.ok + ", ошибок " + p.failed
85	      : "Нет активной обработки");
86	
87	    manual = st.manual || manual;
88	    renderButton();
89	
90	    var t = st.totals || {};
91	    setText("t-total", t.games_total);
92	    setText("t-today", t.processed_today);
93	    setText("t-today-sub", "успешно " + t.processed_today_ok + " · " + st.day);
94	    setText("t-errors", t.errors_today);
