118	          "</td><td>" + esc(r.ok) + "/" + esc(r.selected) + (r.failed ? ", ошибок " + esc(r.failed) : "") + "</td></tr>";
119	      }).join("") : '<tr><td colspan="5" class="muted">Запусков ещё не было</td></tr>';
