153	  function initMonitor() {
154	    var form = document.getElementById("run-form");
155	    var btn = document.getElementById("run-btn");
156	    var bar = document.getElementById("progress-bar");
157	    if (bar) setProgress(Number(bar.dataset.pct || 0));
158	    if (form) {
