160	      manual = {
161	        code: d.code || "ok",
162	        available_at: d.availableAt || null,
163	        runs_today: Number(d.runsToday || 0),
164	        daily_cap: Number(d.dailyCap || 0),
165	        cooldown_seconds: Number(d.cooldown || 0),
166	        retry_after: Number(d.retryAfter || 0),
167	        reason: d.reason || ""
168	      };
169	    }
170	    if (form && window.fetch) {
171	      form.addEventListener("submit", function (ev) {
172	        ev.preventDefault();
173	        pending = true;
174	        btn.disabled = true;
175	        btn.textContent = "Запускаю…";
176	        fetch("/run", { method: "POST", headers: { "Accept": "application/json" }, credentials: "same-origin" })
177	          .then(function (r) { return r.json().then(function (body) { return { status: r.status, body: body }; }); })
178	          .then(function (res) {
179	            flash(res.status === 202 ? "Обработка запущена." : (res.body.detail || "Запуск отклонён."), res.status === 202);
180	          }).catch(function () {
181	            flash("Не удалось связаться с сервером.", false);
182	          }).finally(function () {
183	            pending = false;
184	            renderButton();
185	          });
186	      });
187	    }
188	    setInterval(renderButton, 1000);
189	
190	    var connDot = document.getElementById("conn-dot");
191	    var connText = document.getElementById("conn-text");
192	    if (!window.EventSource) {
193	      connText.textContent = "браузер не поддерживает обновления в реальном времени";
194	      return;
195	    }
196	    var lastLog = 0;
197	    var es;
198	    function connect() {
199	      es = new EventSource("/api/events?last_log=" + lastLog);
200	      es.addEventListener("open", function () {
201	        connDot.className = "dot ok";
202	        connText.textContent = "обновляется в реальном времени";
203	      });
204	      es.addEventListener("status", function (ev) { render(JSON.parse(ev.data)); });
205	      es.addEventListener("log", function (ev) {
206	        var items = JSON.parse(ev.data);
207	        if (items.length) lastLog = items[items.length - 1].id;
208	        appendLogs(items);
209	      });
210	      es.addEventListener("error", function () {
211	        connDot.className = "dot error";
212	        connText.textContent = "соединение потеряно, переподключаюсь…";
213	        es.close();
214	        setTimeout(connect, 3000);
215	      });
216	    }
217	    connect();
218	  }
219	
220	  if (document.getElementById("run-form")) initMonitor();
221	})();
