import json
import sys
import time
import urllib.request

BASE = sys.argv[1]
TOTAL_RUNS = int(sys.argv[2])
LOG = sys.argv[3]


def log(msg):
    with open(LOG, "a", encoding="utf-8") as fh:
        fh.write(time.strftime("%H:%M:%S ") + msg + "\n")


def get(path):
    with urllib.request.urlopen(BASE + path, timeout=30) as r:
        return json.loads(r.read())


def press():
    req = urllib.request.Request(BASE + "/run", method="POST",
                                 headers={"Accept": "application/json", "Sec-Fetch-Site": "same-origin",
                                          "Origin": BASE})
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, json.loads(r.read())
    except urllib.error.HTTPError as e:
        return e.code, json.loads(e.read() or b"{}")


log("driver started")
last_seen = None
while True:
    try:
        st = get("/api/status")
    except Exception as exc:
        log(f"status failed: {exc}")
        time.sleep(30)
        continue
    runs = st.get("runs") or []
    finished = [r for r in runs if r.get("finished_at")]
    if runs and runs[0]["id"] != last_seen:
        last_seen = runs[0]["id"]
        log(f"run #{runs[0]['id']} seen: {runs[0]['status']} {runs[0].get('source_label')}")
    if len(finished) >= TOTAL_RUNS and not st.get("running"):
        log("all runs finished: " + json.dumps([{k: r.get(k) for k in ("id", "trigger", "status", "selected", "ok", "failed", "sources", "seconds")} for r in runs], ensure_ascii=False))
        break
    m = st.get("manual") or {}
    if not st.get("running") and finished and m.get("allowed"):
        code, body = press()
        log(f"pressed the button: {code} {body.get('code')}")
    time.sleep(30)
EOF
